import { existsSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { distanceKm, nearbyAirports } from "@/geo/airports";

// data/airports.csv is generated by `npm run airports` and not committed
const hasData = existsSync(path.join(process.cwd(), "data", "airports.csv"));

describe("distanceKm", () => {
  it("is 0 between a point and itself", () => {
    expect(distanceKm(40.4, -3.7, 40.4, -3.7)).toBe(0);
  });

  it("measures Madrid to Barcelona at about 505 km as the crow flies", () => {
    expect(distanceKm(40.4168, -3.7038, 41.3874, 2.1686)).toBeCloseTo(505, -1);
  });
});

describe.skipIf(!hasData)("nearbyAirports", () => {
  it("finds MAD, and only MAD, around Madrid", () => {
    expect(nearbyAirports(40.4, -3.7)).toEqual(["MAD"]);
  });

  it("finds Orly and Roissy around Paris, nearest first", () => {
    expect(nearbyAirports(48.8566, 2.3522).slice(0, 2)).toEqual(["ORY", "CDG"]);
  });

  it("finds BCN around Barcelona, RUN on La Réunion and GVA near Mont-Saxonnex", () => {
    expect(nearbyAirports(41.3874, 2.1686)[0]).toBe("BCN");
    expect(nearbyAirports(-21.0597, 55.2203)).toContain("RUN");
    expect(nearbyAirports(46.0517, 6.4533)).toContain("GVA");
  });

  it("leaves out military and business-only fields such as Torrejón", () => {
    expect(nearbyAirports(40.4, -3.7)).not.toContain("TOJ");
  });

  it("honours the radius", () => {
    expect(nearbyAirports(40.4, -3.7, 5)).toEqual([]);
    expect(nearbyAirports(40.4, -3.7, 1000).length).toBeGreaterThan(5);
  });

  it("finds nothing in the middle of the ocean", () => {
    expect(nearbyAirports(-40, -120)).toEqual([]);
  });
});
